const slug = (texto) => String(texto).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
const tec = (nivel, nome, acao, custo, resumo, extra = {}) => ({ nivel, nome, acao, custo, resumo, ...extra });
const LIVRO = 'Hijutsus Vol. 2';

export const APTIDOES_VOL2 = [
  { id: slug('Elemento Natural: Fuuton'), nome: 'Elemento Natural: Fuuton', categoria: 'cla', gratuita: false, cla: 'Shimura', pagina: 9, livro: LIVRO, resumo: '[Vol. 2] Requer Espírito 1; Fuuton 1.. Todos os seus efeitos de Fuuton ignoram 2 níveis de dureza (com exceção daquelas provenientes do poder Jinchuuriki), caso o efeito ou técnica de fuuton já ignore níveis de dureza, ele passa a ignorar 2 pontos adicionais (exemplo: Afiar que já ignora 1 ponto de Dureza passa a ignorar 3 pontos de Dureza). Em contrapartida, você não é capaz de aprender ou utilizar nenhum outro poder elemental.', tecnicas: [tec(1, 'Akumu no Kyūin', 'padrao', 0, 'Essa técnica apenas pode ser realizada por um Baku de NC 12 ou maior. Ao abrir a boca, o Baku inicia uma sucção em área, atrapalhando o equilíbrio de todos os atingidos (com exceção do seu invocador) e aumentando drasticamente as técnicas de Fuuton e Katon. Nenhum teste é necessário por parte da invocação.')] },
  { id: slug('Izanagi'), nome: 'Izanagi', categoria: 'cla', gratuita: false, cla: 'Uchiha', pagina: 12, livro: LIVRO, resumo: '[Vol. 2] Requer Sandan Sharingan; Inteligência 14; somente para PdM.. Izanagi pode ser usado de forma idêntica à Falsa Morte (ver em Hipnose Sharingan, Livro Básico, p.187) com a mudança que você pode usá-lo um número de vezes igual à metade do seu nível de Espírito ou Inteligência (o que for maior) na mesma cena. A quantidade de usos da Falsa Morte original e do Izanagi não se misturam. O custo de chakra também é alterado para 10, pago somente no primeiro uso.' },
  { id: slug('Izanami'), nome: 'Izanami', categoria: 'cla', gratuita: false, cla: 'Uchiha', pagina: 14, livro: LIVRO, resumo: '[Vol. 2] Requer Sandan Sharingan; Inteligência 14; somente para PdM.. Para usar essa técnica, escolha um alvo, pague 10 pontos de chakra e gaste uma Ação Padrão. O alvo imediatamente fez um teste de Inteligência, Dif 11 + atributo Inteligência do usuário (já inclusa a Ilusão Profunda), se falhar, é iniciada a gravação da ilusão repetida. No turno seguinte, você deve gastar novamente uma Ação Padrão.' },
  { id: slug('Regeneração de Vigor'), nome: 'Regeneração de Vigor', categoria: 'cla', gratuita: false, cla: 'Uzumaki', pagina: 14, livro: LIVRO, resumo: '[Vol. 2] Requer Vigor 1, Espírito 3.. Um aliado adjacente (a 1m) pode gastar sua ação padrão para morder sua pele. Você sofre 3 de dano fixo e deve gastar chakra igual a ½ do Espírito. Mantendo a mordida até o final do turno, o aliado recupera Vitalidade igual ao Espírito do Uzumaki mordido e Chakra igual à metade deste valor.' },
  { id: slug('Kujaku Myoho: Saimin (Hipnotismo)'), nome: 'Kujaku Myoho: Saimin (Hipnotismo)', categoria: 'cla', gratuita: false, cla: 'Hoshigakure', pagina: 18, livro: LIVRO, resumo: '[Vol. 2] Requer Inteligência 4; Kujaku Myoho 1. Esta aptidão funciona como o efeito “Êxtase” (Ver Livro Básico, p.235) exceto que a dificuldade é igual a 8 + Nível de Kujaku Myoho + ½ da Inteligência. Não é necessário contato visual com a técnica. Esta aptidão somente pode afetar um alvo de cada vez, sendo necessário usar uma ação livre para libertar o alvo anterior antes de tentar utilizar o hipnotismo em outro.' },
  { id: slug('Kujaku Myoho: Sacrifício'), nome: 'Kujaku Myoho: Sacrifício', categoria: 'cla', gratuita: false, cla: 'Hoshigakure', pagina: 18, livro: LIVRO, resumo: '[Vol. 2] Requer Kujaku Myoho 5. Pagando 1 ponto de Saúde (adicional a qualquer outro custo que a técnica possua), o personagem pode adicionar +1 de dano base e +1 de dificuldade de teste em qualquer efeito do poder Kujaku Myoho. O bônus de dano aumenta para +2 quando Kujaku Myoho alcança o Nv 8.', tecnicas: [tec(1, 'Kujaku Myoho: Gen’ei', 'livre', 0, 'Este efeito somente pode ser usado por um personagem morrendo, ele renuncia ao teste de Vigor para despertar da condição inconsciente e desenhar um selo com o próprio sangue contendo sua essência. Caso o personagem morra na mesma cena, ele poderá voltar como um espírito após 2 turnos. A personagem retornada não pode ser morta, afetado por genjutsu ou tocada se não desejar, e possui o chakra completo do usuário.')] },
  { id: slug('Demolição'), nome: 'Demolição', categoria: 'cla', gratuita: false, cla: 'Bakuton', pagina: 20, livro: LIVRO, resumo: '[Vol. 2] Requer Bakuton 5. Quando atacar com qualquer técnica Bakuton, suas técnicas ignoram 2 pontos de dureza de qualquer objeto, barreira ou dureza imaginária que sejam alvo do usuário, exceto aquelas criadas por outras técnicas de Bakuton, se o usuário desejar. Esta aptidão não afeta durezas de corpo de nenhum tipo. Ao alcançar Bakuton 7, Demolição evolui e passa a ignorar 3 pontos de dureza.' },
  { id: slug('Usar Arma: Arsenal'), nome: 'Usar Arma: Arsenal', categoria: 'cla', gratuita: false, cla: 'Buki Senmon', pagina: 23, livro: LIVRO, resumo: '[Vol. 2] Requer Destreza 8. Você se torna proficiente com todas as armas marciais. Você ainda precisa preencher os pré-requisitos de atributo para usá-las sem penalidade. Além disso, caso compre a aptidão “Especialista”, “Dano Extra” e/ou “Crítico Aprimorado”, você receberá seus benefícios para todas as armas.' },
  { id: slug('Acuidade Perfeita'), nome: 'Acuidade Perfeita', categoria: 'cla', gratuita: false, cla: 'Buki Senmon', pagina: 24, livro: LIVRO, resumo: '[Vol. 2] Requer Destreza 8; Acuidade; Usar Arma: Arsenal.. Você é capaz de utilizar destreza para cumprir os pré- requisitos de atributo para uso de qualquer arma. Você considera todas as armas como “Armas Acuradas” (podem ser utilizadas com a aptidão acuidade). Adicionalmente, sempre que utilizar uma arma com acuidade, você pode substituir Força por Destreza no cálculo de dano.' },
  { id: slug('Arsenal Completo'), nome: 'Arsenal Completo', categoria: 'cla', gratuita: false, cla: 'Buki Senmon', pagina: 24, livro: LIVRO, resumo: '[Vol. 2] Requer Usar Arma: Arsenal; Criar Arma ou Fuuinjutsu 2. Você é capaz de possuir um arsenal completo com infinitas armas não especiais ocupando pouco espaço. A forma como isso ocorre é definido pelo jogador, seja um pergaminho possuindo um arsenal completo, como a Tenten, ou um recipiente de metal líquido que se molda a vontade da personagem, por exemplo. Para usar esta aptidão, você deve preparar o arsenal no início da aventura e escolher quantos compartimentos ele ocupa, 1 ou 2.' },
  { id: slug('Mestre de Manobras'), nome: 'Mestre de Manobras', categoria: 'cla', gratuita: false, cla: 'Buki Senmon', pagina: 24, livro: LIVRO, resumo: '[Vol. 2] Requer Guerreiro; Acuidade Perfeita.. Você pode usar Destreza para preencher qualquer pré- requisito de atributo para aptidões de manobra. Você pode adquirir duas aptidões de manobra, à sua escolha, porém somente poderá usá-las estando armado. Você precisa preencher os pré- requisitos das aptidões escolhidas quando comprar “Mestre de Manobras”.' },
  { id: slug('Arte de Combate'), nome: 'Arte de Combate', categoria: 'cla', gratuita: false, cla: 'Chouju-Giga', pagina: 25, livro: LIVRO, resumo: '[Vol. 2] Requer Arte 2. Você pode obter e evoluir o poder restrito Sumi Ninpou. Além disso, você ganha gratuitamente as aptidões Perito: Arte e Perícia Inata: Arte e recebe o dobro de Ryos sempre que utilizar a ação “Sustento” de sua perícia Arte.' },
  { id: slug('Resistência Insaciável'), nome: 'Resistência Insaciável', categoria: 'cla', gratuita: false, cla: 'Daikiga', pagina: 31, livro: LIVRO, resumo: '[Vol. 2] Você recebe dureza de corpo 1 contra todos os tipos de dano. Com Vigor 10, aumenta para dureza de corpo 2. E com Vigor 14, aumenta para dureza de corpo 3.' },
  { id: slug('Ingestão de Chakra'), nome: 'Ingestão de Chakra', categoria: 'cla', gratuita: false, cla: 'Daikiga', pagina: 31, livro: LIVRO, resumo: '[Vol. 2] Requer Espírito 1.. Você é capaz de absorver chakra diretamente de um ser vivo. Contudo, para que isso seja possível, é necessário que a vítima esteja sob a condição Indefeso. Absorver chakra é uma ação padrão e tem duração por concentração.' },
  { id: slug('Rakanken (Punho Arhat)'), nome: 'Rakanken (Punho Arhat)', categoria: 'cla', gratuita: false, cla: 'Daikiga', pagina: 32, livro: LIVRO, resumo: '[Vol. 2] Requer Força 4; Ingestão de Chakra; Lutador. Rakanken é um estilo de luta totalmente grosseiro e pesado. Seus ataques são extremamente poderosos e certeiros, podendo destroçar o seu inimigo com apenas alguns golpes básicos. Ao comprar essa aptidão, você recebe gratuitamente o acesso à aptidão Punho de Ferro.' },
  { id: slug('Terra Insaciável'), nome: 'Terra Insaciável', categoria: 'cla', gratuita: false, cla: 'Daikiga', pagina: 32, livro: LIVRO, resumo: '[Vol. 2] Requer Ingestão de Chakra; Doton Nv 6; Barreira Nv 3 (Doton).. Você tem a capacidade de drenar chakra através de suas barreiras do poder Doton. Ao comprar essa aptidão, você recebe gratuitamente o efeito Barreira Nv 6 para seu poder Doton. Além disso, você poderá utilizá-la com CC, em vez de CD, para prender o oponente, ou CC em vez de LM+2 para se defender.' },
  { id: slug('Doton: Efeitos Para Daikiga'), nome: 'Doton: Efeitos Para Daikiga', categoria: 'cla', gratuita: false, cla: 'Daikiga', pagina: 33, livro: LIVRO, resumo: '[Vol. 2] Requer Ingestão de Chakra; Terra Insaciável.. direito a novos efeitos para Doton. Pré-requisito: Ingestão de Chakra; Terra Insaciável. EFEITOS DE NÍVEL 4', tecnicas: [tec(1, 'Cortina de Poeira', 'parcial', 0, 'Pré-requisito: Lutar às Cegas (Aptidão) ou habilidade de sensor; Tremor (Efeito de Doton) Ação: Parcial Alcance: ver texto Alvo: O ambiente Duração: Contínua; turnos iguais ao Nível de Poder usado Área de Efeito: Ver texto Você bate no solo com força o suficiente para abalar as estruturas de quaisquer pessoas que estiverem em pé e levantar uma enorme cortina de fumaça. Você deve executar esse efeito em conjunto com…', { fica: 'Cortina de Poeira (concentração)' }), tec(1, 'Golem de Terra Insaciável', 'movimento', 0, 'Ação: Movimento Alcance: Pessoal Duração: Contínua (ver texto) Selos de Mão: Não Ao abrir a boca, você expele lama e pedra para formar um golem de terra que segue as regras do efeito Golem de Pedra do poder Jinton (Ver Este Livro p.71), com exceção das modificações a seguir. O ataque corporal do golem de terra drena chakra da vítima, em uma razão igual a ¼ do Espírito do usuário. O chakra perdido é totalmente…', { fica: 'Golem de Terra Insaciável' })] },
  { id: slug('Seis Braços'), nome: 'Seis Braços', categoria: 'cla', gratuita: false, cla: 'Gorudogumo', pagina: 34, livro: LIVRO, resumo: '[Vol. 2] Requer Destreza 4. O personagem nasce ou desenvolve durante sua vida 4 braços extras, ficando com 3 braços de cada lado do corpo. Com isso, você ganha a habilidade de realizar Selos de Mão enquanto segura algum objeto, desde que possua uma mão de cada lado do corpo livre. Os 4 braços extras ganhos por conta dessa aptidão não têm finalidade nenhuma a não ser para as tarefas citadas nesse Hijutsu, ou seja, para qualquer outro quesito de Aptidões e combate, considere esse personagem apenas como alguém com dois braços.' },
  { id: slug('Ouro Pegajoso'), nome: 'Ouro Pegajoso', categoria: 'cla', gratuita: false, cla: 'Gorudogumo', pagina: 35, livro: LIVRO, resumo: '[Vol. 2] Requer Espírito 8; Kumo Ninpou 4.. Você recebe gratuitamente o Efeito Nível 2: Criar Arma, junto com suas evoluções, para o efeito Kumo Ninpou. Além disso, você ganha à possibilidade de criar Arcos Longos e Arcos Compostos com o efeito Criar Arma. Ao utilizar esse efeito, a arma criada possui +1 de dano de arma e +2 de Dureza.' },
  { id: slug('Olho de Aranha'), nome: 'Olho de Aranha', categoria: 'cla', gratuita: false, cla: 'Gorudogumo', pagina: 35, livro: LIVRO, resumo: '[Vol. 2] Requer Percepção 12; Espírito 8.. Um terceiro olho surge em sua testa, fazendo você aumentar drasticamente sua percepção. Normalmente esse olho fica tampado pela sua bandana, e retirá-la é uma ação livre. Ativar e manter o olho é uma ação parcial, que consome 1 de Chakra.' },
  { id: slug('Kyodaigumo (Aranha Gigante)'), nome: 'Kyodaigumo (Aranha Gigante)', categoria: 'cla', gratuita: false, cla: 'Gorudogumo', pagina: 37, livro: LIVRO, resumo: '[Vol. 2] Requer Kuchiyose 6 (Aranhas). Pré-requisito: Kuchiyose 6 (Aranhas) Com essa técnica, você se torna capaz de invocar a Kyodaigumo, a mãe aranha. Kyodaigumo é uma aranha preta gigante com listras laranjas que descem na parte de trás do seu abdômen. Assemelha-se muito a uma tarântula.', tecnicas: [tec(1, 'Kumo Soukei', 'padrao', 1, 'Você pode enviar chakra através de teias de aranha para instantaneamente detectar a aproximação de todos os inimigos tolos o bastante para tocar na teia. Estes pontos espalhados em todas as direções são tão sensíveis que nem mesmo a menor perturbação do ar passará despercebida. Além disso, os fios são tão finos, que dificilmente podem ser vistos.'), tec(1, 'Kumo Sausei Tekunikku', 'parcial', 0, 'Você pode criar teia a partir das pontas dos dedos e utilizá-la como se fosse um tipo de Kousen natural. Utilizar esses Kousens naturais ainda requer a aptidão Usar Arma. Criar esses Kousens não custa chakra e utilizá-los segue a mesma regra do Kousen normal (ver Livro Básico, p.132).')] },
  { id: slug('Posessão da Serpente Branca'), nome: 'Posessão da Serpente Branca', categoria: 'cla', gratuita: false, cla: 'Hebinomichi', pagina: 42, livro: LIVRO, resumo: '[Vol. 2] Requer Ocultismo 2; Espírito 2. Como um iniciado na arte oculta dos Caminhos da Serpente, você recebe +1 compartimento extra, que se localiza em seu estômago, além de aumentar o número de compartimentos que podem ser carregados sem penalização para 4 invés de 3. Retirar um item do seu estômago, pela boca, custa a mesma ação que seria usada para tirá-lo de qualquer outro compartimento. Saque Rápido pode ser usado com esse compartimento.' },
  { id: slug('Yamata no Jutsu'), nome: 'Yamata no Jutsu', categoria: 'cla', gratuita: false, cla: 'Hebinomichi', pagina: 42, livro: LIVRO, resumo: '[Vol. 2] Requer Ocultismo 11; Possessão da Serpente Branca; Hebi. Você é capaz de assumir a forma de uma serpente tamanho Enorme, ganhando todos os bônus por tamanho, além de um bônus em Destreza igual aos de Força e Vigor, e 1 de Dureza de Corpo passivamente, porém, nessa forma você fica incapaz de utilizar qualquer arma ou técnica além daquelas do Poder Hebi Ninpou (que passarão a ser executadas sem selos de mão e sem penalidade por combate próximo). Usar esta aptidão é uma ação de movimento, custa 5 pontos de chakra e tem duração contínua. Nível 2: Assim que alcançar…', tecnicas: [tec(1, 'Sōjasōsai no Jutsu', 'padrao', 10, 'O Jutsu de Sacrifício das Serpentes Gêmeas é uma técnica que remete a romances antigos onde dois amantes se sacrificavam juntos para poderem viver juntos eternamente no pós vida. Consiste numa técnica de alto sacrifício que instantaneamente seu alvo. Para isso é necessário estar adjacente ao seu alvo e fazer uma jogada de CC contra a Defesa do Alvo para segurar sua mão e forçar o selo em conjunto do seu.')] },
  { id: slug('Usar Armas de Jashin'), nome: 'Usar Armas de Jashin', categoria: 'cla', gratuita: false, cla: 'Jashin Juusha', pagina: 44, livro: LIVRO, resumo: '[Vol. 2] Requer Ocultismo 4, Força 4.. Você recebe proficiência com as Foice de Jashin e Lança Retrátil, podendo usá-las sem penalidades de precisão. Você ainda precisa preencher os pré-requisitos de Força específicos de cada arma. Especialista: Além disso, caso compre a aptidão “Especialista”, “Dano Extra” e/ou “Crítico Aprimorado”, você receberá seus benefícios para todas as armas Jashin.' },
  { id: slug('Ritual de Conexão'), nome: 'Ritual de Conexão', categoria: 'cla', gratuita: false, cla: 'Jashin Juusha', pagina: 45, livro: LIVRO, resumo: '[Vol. 2] Requer Ocultismo 8.. Agora você pode fazer o ritual de conexão de Jashin. Perfuração Variações: A técnica do Ritual de Conexão possui duas variações, uma utilizando o próprio corpo como canalizador (Conexão-Corpo) e outra usando um boneco (Conexão-Boneco). Ao comprar essa aptidão, você é capaz de usar ambas as variações, que podem ser vistas mais adiante em Técnicas.' },
  { id: slug('Imortalidade'), nome: 'Imortalidade', categoria: 'cla', gratuita: false, cla: 'Jashin Juusha', pagina: 45, livro: LIVRO, resumo: '[Vol. 2] Requer Regeneração, Duro de Matar, Vigor 10. Você consegue a imortalidade, apenas por seguir Jashin. Você é imune à condição morrendo (porém sangramentos ainda geram perda de Vit) e consegue continuar em combate mesmo com Vitalidade entre 0 e -20. Ao alcançar Vit -21, seu corpo não resiste aos danos e você é decapitado; você fica indefeso, totalmente incapaz de se mover e fora de combate, restando somente sua cabeça, mas ainda vivo.' },
  { id: slug('Combatente Sádico'), nome: 'Combatente Sádico', categoria: 'cla', gratuita: false, cla: 'Jashin Juusha', pagina: 46, livro: LIVRO, resumo: '[Vol. 2] Requer Usar Armas de Jashin, Ocultismo 12.. Você pode escolher uma das 2 técnicas a seguir quando compra essa aptidão: Bastião Insano ou Avanço Ofensivo (ver mais adiante em Técnicas). Combatente Sádico aprimorado: [Requer Ocultismo 16] Você pode comprar pela segunda vez essa aptidão, conseguindo a técnica que não foi escolhida anteriormente.' },
  { id: slug('Jashinista Experiente'), nome: 'Jashinista Experiente', categoria: 'cla', gratuita: false, cla: 'Jashin Juusha', pagina: 46, livro: LIVRO, resumo: '[Vol. 2] Requer Ocultismo 16; Ritual de Conexão; Imortalidade.. com mais facilidade. Pré-requisito: Ocultismo 16; Ritual de Conexão; Imortalidade. Ritual melhorado: Mesmo que consiga um resultado 13 nos dados de uma jogada de ataque, você consegue o sangue da pessoa para fazer o ritual na ponta de sua arma, mas o dano será de grau 3 e não causará sangramento.', tecnicas: [tec(1, 'Conexão-corpo', 'completa', 4, 'Selos de Mão: Não Condições: Para praticar o ritual, você precisa de sangue da vítima (geralmente por acertar um golpe que cause sangramento) e ela estar dentro do alcance dessa técnica. Uma vez feito o ritual, a vítima pode se afastar o quanto quiser que a técnica ainda fará efeito. Ritual: Você inicia criando o símbolo de jashin com o sangue da vítima, um círculo com um triângulo interno que ocupa 1m de diâmetro…'), tec(1, 'Conexão-boneco', 'completa', 4, 'Selos de Mão: Não A técnica funciona similar a variação com o próprio corpo, exceto pelas seguintes alterações: Condições: Para praticar o ritual com o boneco, você precisa do sangue do alvo e um boneco de madeira, feito por e para especificamente um jashinista. Ambos o alvo e boneco devem estar no alcance da técnica (e dentro do círculo ritualístico). Ferimentos: Todo o dano causado ao boneco também é causado na…'), tec(1, 'Pontos Vitais', 'padrao', 0, 'Durante o Ritual de Conexão, você é capaz de acertar os pontos vitais, sabendo exatamente onde eles estão. Você realiza um ataque da manobra golpear em si mesmo visando algum órgão vital. Ao fazer isso, você e a vítima do ritual sofrem, no mínimo, grau de dano 2, e ambos também sofrem 1 nível de sangramento.'), tec(1, 'Bastião Insano', 'parcial', 0, 'Você deve escolher esta técnica como uma das opções disponíveis pela aptidão Combatente Sádico. Após receber um golpe de um inimigo, você pode abrir sua guarda e chamar a atenção de todos enquanto luta, dando a todos os inimigos uma penalidade de -2 para acertar alvos que não sejam você até o fim do combate. Você não recebe qualquer bônus de precisão de defesa enquanto estiver utilizando esta técnica (com exceção…', { fica: 'Bastião Insano (até o fim do combate)' }), tec(1, 'Avanço Ofensivo', 'parcial', 0, 'Você deve escolher esta técnica como uma das opções disponíveis pela aptidão Combatente Sádico. Você realiza a manobra Investida com ambas as armas Jashin e ataca o inimigo. O ataque recebe +1 de bônus de dano e +0,5 no grau de dano.')] },
  { id: slug('Sensibilidade Auditiva'), nome: 'Sensibilidade Auditiva', categoria: 'cla', gratuita: false, cla: 'Jingokuon', pagina: 49, livro: LIVRO, resumo: '[Vol. 2] Requer Percepção 4. Você pode manipular a sensibilidade de seus ouvidos, permitindo ouvir qualquer faixa de frequência sonora (como ondas de rádio e sonares) ou amplificar/reduzir a intensidade que os sons chegam neles. Você se torna imune a qualquer Efeito exclusivo de Ototon e ganha acesso à técnica Osekkai. Sensor: Ao atingir Rastrear 8, ganha os benefícios da aptidão Sensor Limitado para Audição, podendo detectar entidades que se movam ou façam o mínimo barulho possível.' },
  { id: slug('Tubos de Ar'), nome: 'Tubos de Ar', categoria: 'cla', gratuita: false, cla: 'Jingokuon', pagina: 50, livro: LIVRO, resumo: '[Vol. 2] Requer Destreza 6. O personagem tem tubos de ar implantados nos braços, com saídas na palma das mãos. Eles amplificam seus ataques de Ototon, aumentando o alcance do poder para Médio (10m + 2m por nível de Espírito) e o dano base em +2. Poderá utilizar os poderes Ototon ou Fuuton sem selos de mão, exceto efeitos exclusivos.' },
  { id: slug('Kyoumei Supika (Alto-falante Ressoante de Eco)'), nome: 'Kyoumei Supika (Alto-falante Ressoante de Eco)', categoria: 'cla', gratuita: false, cla: 'Jingokuon', pagina: 50, livro: LIVRO, resumo: '[Vol. 2] Requer Acuidade e Destreza 6; ou Força 6. Você se torna apto a equipar e utilizar o Alto-falante Ressonante de Eco, uma Arma Marcial Leve, porém que pode ser utilizada com Força ou Destreza 6, e que ainda possui as seguintes características: Dano Alcance Crítico Compartimentos Tipo +2 --- 15-16 1 item/1 comp. Esmagamento Preço: 500 Ryo Dureza: 25 Kyoumei Supika: O alto-falante funciona como uma Manopla, mas que é usado em apenas um dos braços. Possui um formato oco, com buracos em uma superfície de metal, que permite que o som entre ou saia com impulso de…' },
  { id: slug('Reverberação'), nome: 'Reverberação', categoria: 'cla', gratuita: false, cla: 'Jingokuon', pagina: 51, livro: LIVRO, resumo: '[Vol. 2] Requer Ototon 5.. Suas habilidades de Ototon ecoam por onde são aplicadas, afetando alvos colaterais. Escolha um efeito exclusivo de Ototon e suas respectivas evoluções. Ele passa a ter Área de Efeito circular de diâmetro máximo de 6m.' },
  { id: slug('Corpo de Fios'), nome: 'Corpo de Fios', categoria: 'cla', gratuita: false, cla: 'Jiongu', pagina: 58, livro: LIVRO, resumo: '[Vol. 2] Requer Ocultismo 2. você se tornar capaz de comprar e evoluir o poder Jiongu e de utilizar a técnica Membros Esticáveis. Nível 2: Quando atingir Ocultismo 10, você pode comprar novamente essa aptidão para evoluí-la. Seu domínio sobre a nova anatomia avançou muito além o dos iniciantes na arte Jiongu, te permitindo utilizar de novas técnicas avançadas, como a “Costura de Membros” e o “Tentáculo de Fios”.' },
  { id: slug('Chakra Expandido Jiongu'), nome: 'Chakra Expandido Jiongu', categoria: 'cla', gratuita: false, cla: 'Jiongu', pagina: 59, livro: LIVRO, resumo: '[Vol. 2] Requer Jiongu 1; Ocultismo 2. Esta aptidão aumenta a quantidade total de chakra do personagem em 10% para cada coração além do primeiro (totalizando 40% de chakra extra, com 5 corações), desde que esse coração possua alguma natureza de chakra associada (ou seja, corações de animais, criaturas vivas e não shinobis não fornecemo o bônus de chakra desta aptidão). Perder ou adicionar um coração não afeta o chakra atual, somente o chakra total máximo. Entretanto, nunca é possível ter mais chakra atual que chakra total, e se isso ocorrer, reduza o…', tecnicas: [tec(1, 'Membros Esticáveis', 'parcial', 2, 'É possível utilizar dos fios do seu corpo para estender e esticar os membros do usuário para aproveitar de maior alcance. Para fazer isso o usuário deve declarar o uso dessa técnica e pagar os custos de chakra e ação para obter os benefícios dessa técnica de forma sustentada. Seus membros são uma extensão de você e podem ser alvo de ataques, o que causará dano ao usuário e, caso recebam um crítico de dano cortante,…', { fica: 'Membros Esticáveis' }), tec(1, 'Costura de Membros', 'padrao', 0, 'Um usuário experiente de Jiongu é capaz de utilizar da estrutura de corpo de fios com extrema aptidão de forma a ser capaz de restaurar até os piores ferimentos. Gastando uma ação parcial e 3 de chakra o usuário pode eliminar toda condição de sangramento em si ou de um alvo. Com mais tempo o usuário pode restaurar qualquer membro amputado como se fosse novo, para isso é necessário o tempo de uma cena (1 hora), um…'), tec(1, 'Tentáculo de Fios', 'parcial', 0, 'Considerada uma versão melhorada dos membros esticáveis, o usuário domina a estrutura de fios de seu corpo modificado pelo Jiongu para criar estruturas similares a tentáculos capazes de fazer curvas, contorcer-se, perseguir, agarrar e atacar seus oponentes, mesmo à distância. Utilizar Tentáculo de Fios te impede de utilizar Membros Esticáveis enquanto a outra estiver sustentada. Criação: Com uma ação parcial e…', { fica: 'Tentáculo de Fios' }), tec(1, 'Hasukonsutorakuto', 'padrao', 0, 'Custo de Corações: 1 (ou mais) Corações por Hasukonsutoraku (Ver Texto) Essa técnica segue as mesmas regras da aptidão Clone, tendo ainda os seguintes efeitos diferenciados: Corações: Os Hasukonsutoraku necessitam de ao menos 1 coração para existirem, ao usar essa técnica o usuário declara quais corações ele retirará de seus “Espaços de Coração”, perdendo sua capacidade de usar os elementos dos corações que ele não…')] },
  { id: slug('Peso do Ouro'), nome: 'Peso do Ouro', categoria: 'cla', gratuita: false, cla: 'Jiongu', pagina: 64, livro: LIVRO, resumo: '[Vol. 2] Requer Sakin 5. Seus efeitos de Sakin ganham +1 de dificuldade de teste. Além disso, todos os seus efeitos e técnicas de Sakin que entrem em contato com o inimigo tem chance de deixar resquícios de pós de ouro nos inimigos, deixando-os lentos e pesados, fazendo com que precisem se esforçar mais para realizar algumas tarefas físicas. Aplicando o Pó de Ouro: Você pode aplicar pó de ouro ao inimigo das seguintes maneiras: 1.' },
  { id: slug('Marca de Ferro'), nome: 'Marca de Ferro', categoria: 'cla', gratuita: false, cla: 'Jiongu', pagina: 65, livro: LIVRO, resumo: '[Vol. 2] Requer Satetsu 5. Seus efeitos de Satetsu ganham +1 de dano. Além disso, todos os seus efeitos e técnicas de Satetsu tem chance de deixar resquícios de areia de ferro grudados no inimigo. Seus efeitos e técnicas de Satetsu que causam grau de dano 3 ou maior marcam o inimigo com areia de ferro imbuída com sua energia magnética, fazendo com que o próximo ataque de Satetsu seja atraído pela areia de ferro presa no alvo.' },
  { id: slug('Kakuran Tensai'), nome: 'Kakuran Tensai', categoria: 'cla', gratuita: false, cla: 'Jiton', pagina: 70, livro: LIVRO, resumo: '[Vol. 2] Esse é um suplemento para o Hijutsu Tensai (Genialidade), oferecendo uma nova opção de jogo. Aptidão Especial: Kakuran Taijutsu.' },
  { id: slug('Kakuran Taijutsu (Taijutsu da Agitação)'), nome: 'Kakuran Taijutsu (Taijutsu da Agitação)', categoria: 'cla', gratuita: false, cla: 'Jiton', pagina: 71, livro: LIVRO, resumo: '[Vol. 2] Requer Força ou Destreza 12, Acrobacia 12, Ponto Cego. Você deve escolher esta aptidão como uma das duas Aptidões Especiais que tem direito pelo Hijutsu Tensai. Ao atacar um inimigo poderá realizar uma Finta como uma ação livre e usar Acrobacia como parâmetro para o teste. Kakuran também anula os bônus da Visão Acelerada do Sharingan, mas não o benefício de Intuição.', tecnicas: [tec(1, 'Akurobatto (Acrobata)', 'padrao', 0, 'Esta técnica permite brandir até 7 espadas super-vibrantes simultaneamente. Atacar com 3 ou mais espadas impede você de receber qualquer bônus de dano, com exceção de Dano Extra. Quando ataca com esta técnica, todos os ataques são considerados')] },
  { id: slug('Elemento Natural: Terra'), nome: 'Elemento Natural: Terra', categoria: 'cla', gratuita: false, cla: 'Jinton', pagina: 72, livro: LIVRO, resumo: '[Vol. 2] Requer Doton 1. Seu domínio sobre o Elemento Terra é maior do que os dos outros, dando a você acesso a novos efeitos. Além disso, recebe +1 de dano base adicional para todas as técnicas de Doton.' },
  { id: slug('Apagar Presença'), nome: 'Apagar Presença', categoria: 'cla', gratuita: false, cla: 'Jinton', pagina: 72, livro: LIVRO, resumo: '[Vol. 2] Requer Sensor; Rastrear 10;. o seu Sensor passa a ser capaz de diferenciar as assinaturas de chakra e medir sua quantidade. Supressão de Forma: [requer Suiton 5 ou Jinton 5] Esta técnica permite ao usuário suprimir seu chakra e sua forma ao ponto de se tornar completamente indetectável e invisível, mediante concentração. Com essa técnica, você recebe os benefícios de camuflagem total e para ser detectado por um shinobi sensor o inimigo deverá passar em um teste de Rastrear, com dificuldade igual a 9 + nível de Espírito do personagem.' },
  { id: slug('Fissão'), nome: 'Fissão', categoria: 'cla', gratuita: false, cla: 'Jinton', pagina: 73, livro: LIVRO, resumo: '[Vol. 2] Requer Espírito 16; Vigor 8. Graças a um poderoso Ninjutsu, você é capaz de separar seu corpo em duas partes iguais, indistinguíveis uma da outra, uma Duplicata perfeita. Fazer isso é uma ação de movimento e custa 12 pontos de Vitalidade. A técnica não requer selos de mão e pode ser utilizada como alternativa ao Kawarimi no Jutsu, se separando na hora de um golpe e realizando o teste de Furtividade normalmente (você ainda só pode usar um único Kawarimi no Jutsu).', tecnicas: [tec(1, 'Redução de Peso', 'parcial', 0, 'Controlando a gravidade ao seu entorno, você fica mais leve do que o ar, podendo até mesmo voar. Você passa a usar a perícia Voo com nível igual ao atributo Espírito. Considera-se que você seja uma criatura alada para questões de combate aéreo.'), tec(1, 'Adição de Peso', 'movimento', 0, 'Adição de Peso funciona como o efeito Pele de Pedra Nv 6 (Doton), porém com as seguintes mudanças. Socos Pesados: [custo de chakra do Pele de Pedra] Você recebe 1 de Dureza de Corpo extra (2 de Dureza de Corpo no total) quando usar esse efeito de forma sustentada. Quando usar Socos de Pedra, seu dano de arma sobe para +5.', { fica: 'Adição de Peso' }), tec(1, 'Golem de Pedra', 'movimento', 0, 'Ação: Movimento Alcance: Pessoal Duração: Contínua (ver texto) Selos de Mão: Não Ao abrir a boca, você expele lama e pedra para formar um golem de pedra de tamanho grande, com o dobro da dureza comum do poder. Ficha: As precisões de seus testes são iguais às precisões do personagem, com uma penalidade de precisão de -3, com a aplicação dos modificadores de tamanho. O ataque corporal do golem de pedra causa dano…', { fica: 'Golem de Pedra' })] },
  { id: slug('Boca de Moldagem'), nome: 'Boca de Moldagem', categoria: 'cla', gratuita: false, cla: 'Kibaku Nendo', pagina: 80, livro: LIVRO, resumo: '[Vol. 2] Requer Arte 12; Kibaku Nendo 6. Desde que possua matéria-prima para tal, usando uma Ação Completa é possível criar Bombas de Argila igual 2x o nível de Arte do usuário (+4 Bombas Adicionais se possuir Perito: Arte ou Perícia Inata: Arte, cumulável entre si). Considere qualquer fonte de argila ou barro como material o bastante para usar essa aptidão indiscriminadamente e 1 compartimento de matéria-prima é o bastante para usar essa aptidão 10 vezes.', tecnicas: [tec(1, 'Nendo Bunshin', 'padrao', 0, 'Custo de Argila: 1 ou mais (ver texto) Essa técnica segue as mesmas regras da aptidão Clone, tendo ainda os seguintes benefícios diferenciados: Nendo Bunshin pode ser usado como material e ponto de ativação para qualquer efeito Kibaku Nendo. Para fazer isso, é necessário ter a quantidade de Bombas de Argila mínima dentro do clone para realizar a técnica. Fazer isso destrói o Nendo Bunshin, com exceção do efeito…'), tec(1, 'Nendo Bunshin Volátil', 'completa', 0, 'Custo de Argila: Nível usado do poder Essa técnica segue as mesmas regras da aptidão Clone e do Nendo Bunshin (Clone de Argila), tendo ainda os seguintes benefícios diferenciados: Esse Nendo Bunshin funciona como um efeito Inflamável Nv. 8 no Modo Contínuo (ver Guia Avançado do Shinobi, p.29), além de um Clone normal. Qualquer efeito Katon ou Kibaku Nendo que afete o Nendo Bunshin, desde que seja um efeito de…')] },
  { id: slug('Kuchiyose: Doninha'), nome: 'Kuchiyose: Doninha', categoria: 'cla', gratuita: false, cla: 'Kuchiyose', pagina: 81, livro: LIVRO, resumo: '[Vol. 2] [Invocação para o poder Kuchiyose] Doninhas armadas que também utilizam o elemento Vento, podendo gerar ataques poderosíssimos. Tamanho: Doninhas são limitadas até o tamanho médio. Atributos Principais: Agilidade, Espírito e Destreza.', tecnicas: [tec(1, 'Kirikiri Mai', 'completa', 0, 'Você é capaz de realizar ao mesmo tempo uma invocação de doninha e uma técnica do seu poder Fuuton com uma ação completa. A doninha invocada deve ser no mínimo de NC 12 e deve ser de tamanho médio. A técnica usada deve ser de alcance à distância, duração instantânea e necessitar no máximo uma ação padrão para ser executada.')] },
  { id: slug('Kuchiyose: Marisco'), nome: 'Kuchiyose: Marisco', categoria: 'cla', gratuita: false, cla: 'Kuchiyose', pagina: 83, livro: LIVRO, resumo: '[Vol. 2] [Invocação para o poder Kuchiyose] Mariscos shinobis são criados principalmente na Vila da Névoa Oculta, no País da água, inclusive já foi criatura invocação do Nidaime Mizukage do Clã Hozuki. Apesar de não serem muito ofensivas, elas possuem capacidade de auxiliar com névoa ilusória de Genjutsu. Invocação Unitária: você somente pode invocar um único marisco por cena.' },
  { id: slug('Kuchiyose: Salamandra'), nome: 'Kuchiyose: Salamandra', categoria: 'cla', gratuita: false, cla: 'Kuchiyose', pagina: 84, livro: LIVRO, resumo: '[Vol. 2] [Invocação para o poder Kuchiyose] Invocação Unitária: você somente pode invocar uma única salamandra por cena. Tamanho Único: Salamandra é limitada até o tamanho enorme. Atributos Principais: Força, Agilidade, Inteligência e Vigor.', tecnicas: [tec(1, 'Dokugiri', 'padrao', 5, 'A salamandra é capaz de produzir veneno, podendo guardar até 1 compartimento de veneno dentro de si por categoria de tamanho a cima do Médio. Os parâmetros do veneno são decididos pela perícia de Venefício do Invocador e somente invocações de NC 12 ou maior possuem essa qualidade. Ao invocar a Salamandra você pode definir qual o veneno existente em cada compartimento, dentre aqueles que você é capaz de produzir.'), tec(1, 'Engolimento', 'completa', 0, 'Ninjutsu Rank B Pré-requisito: Imergir Ação: Completa Alcance: Pessoal Engolimento: Quando a Salamandra está imersa no solo, caso tenha sido bem-sucedida no teste de Furtividade, pode usar a manobra Agarrar como um ataque furtivo em um alvo que esteja imediatamente acima de sua posição. Ela salta para fora engolindo o alvo, tudo isso como uma Ação Completa. A vítima deve ser uma categoria de tamanho menor que a da…')] },
  { id: slug('Kuchiyose: Tartaruga'), nome: 'Kuchiyose: Tartaruga', categoria: 'cla', gratuita: false, cla: 'Kuchiyose', pagina: 86, livro: LIVRO, resumo: '[Vol. 2] [Invocação para o poder Kuchiyose] Tartarugas ninja, munidas de grande defesa com seus cascos, grande resiliência e capacidade de se mover na água com grande habilidade. Atributos Principais: Força; Percepção; Inteligência e Vigor Perícias: Atletismo (Somente Nadar), Ciência Natural, Cultura, Ocultismo e Procurar. Poderes: Nenhum Aptidões: Crítico Aprimorado, Combate Defensivo; Especialista, Intuição, Lutador, Trespassar, Ataque Atordoante, Ataque Giratório, Ataque Poderoso, Bloquear Arma, Contragolpe, Derrubar Agressivo, Desarme Agressivo, Duro de…' },
  { id: slug('Kugutsu (Marionetes)'), nome: 'Kugutsu (Marionetes)', categoria: 'cla', gratuita: false, cla: 'Kugutsu', pagina: 87, livro: LIVRO, resumo: '[Vol. 2] Requer Mecanismos 4; Engenheiro (aptidão). Você é capaz de construir e utilizar marionetes em combate. São armas de longo alcance que podem ser usadas de forma ofensiva, defensiva ou como suporte, e são controladas por fios de chakra, que são conectados aos dedos do usuário. As marionetes são usadas como armas por um restrito grupo de ninjas chamados de marionetistas.' },
  { id: slug('Estrangular'), nome: 'Estrangular', categoria: 'cla', gratuita: false, cla: 'Kugutsu', pagina: 97, livro: LIVRO, resumo: '[Vol. 2] Requer Mecanismos 12; Exclusivo para marionete. Ao ser bem-sucedido em um teste de Agarrar, você pode imediatamente começar a estrangular o alvo com sua marionete enquanto mantém a manobra. Além de sofrer a condição agarrado, o alvo também sofre sufocamento, com teste de resistência de Dif 8 + Mecanismos e dano fixo de sufocamento igual ao nível de Mecanismos. As demais regras da manobra agarrar e de sufocamento são mantidas.' },
  { id: slug('Kurohigi (Estilo Secreto Negro)'), nome: 'Kurohigi (Estilo Secreto Negro)', categoria: 'cla', gratuita: false, cla: 'Kugutsu', pagina: 97, livro: LIVRO, resumo: '[Vol. 2] Requer Kugutsu; Prestidigitação 6; Mecanismos 6. Você é capaz de confeccionar e controlar marionetes Médias. Normal: O marionetista ainda não tem conhecimentos aprofundados sobre o Kugutsu e somente pode fazer e controlar marionetes Pequenas. NÍVEL 2 Pré-requisitos: Kugutsu; Prestidigitação 10 Benefício: Você pode controlar duas marionetes por vez.' },
  { id: slug('Shirohige'), nome: 'Shirohige', categoria: 'cla', gratuita: false, cla: 'Kugutsu', pagina: 98, livro: LIVRO, resumo: '[Vol. 2] Requer Kurohigi; Mecanismos 16; Prestidigitação 16;. Você pode controlar até 10 marionetes médias ao mesmo tempo, utilizando os benefícios de ações de Kurohigi. Pode invocar essas 10 marionetes a partir de um único pergaminho, pagando o custo de invocação de cada uma. Cada uma das marionetes de Shirohigi tem direito a 3 aptidões sem custos.' },
  { id: slug('Akahige'), nome: 'Akahige', categoria: 'cla', gratuita: false, cla: 'Kugutsu', pagina: 98, livro: LIVRO, resumo: '[Vol. 2] Requer Shirohigi; Mecanismos 18; Prestidigitação. Uma vez por cena, você pode invocar 100 marionetes sem dispositivos e aptidões a partir de um único pergaminho, que ficam distribuídas em uma área em volta do usuário com raio de 10m +2m por Espírito (o alcance do controle). Invocá-las e ligar os fios têm um custo de 40 de chakra. Considere que as 100 marionetes formam um único conjunto de marionetes médias com 1 de dureza de corpo e Absorção igual a10x Mecanismos de Absorção.' },
  { id: slug('Kuroi Kaminari (Relâmpago Negro)'), nome: 'Kuroi Kaminari (Relâmpago Negro)', categoria: 'cla', gratuita: false, cla: 'Tensai', pagina: 105, livro: LIVRO, resumo: '[Vol. 2] A técnica do Relâmpago Negro, utilizado pelo 3º Raikage e passado para Darui da aldeia da nuvem. Aqueles que portam essa técnica são tatuados em alguma parte do corpo com o kanji “Relâmpago”. A principal característica é que o seu Raiton passa a possuir uma cor negra.' },
  { id: slug('Relâmpago Negro'), nome: 'Relâmpago Negro', categoria: 'cla', gratuita: false, cla: 'Tensai', pagina: 105, livro: LIVRO, resumo: '[Vol. 2] Requer Raiton 5; Domínio do Raio. Pagando um custo adicional de +2 no custo de chakra, ao utilizar um efeito Raiton, o benefício do seu Domínio do Raio é ampliado e você consegue um crítico com 2 pontos a menos no resultado dos dados. Assim, se o crítico do efeito é 15-16, passa a ser 13-14-15-16. Este benefício não é cumulativo com a Lâmina de Raios Nv 9 e nem afeta o' },
  { id: slug('Flautista'), nome: 'Flautista', categoria: 'cla', gratuita: false, cla: 'Mateki', pagina: 106, livro: LIVRO, resumo: '[Vol. 2] Requer Inteligência 4; Fascinar. Você é versado na arte de tocar flautas, além disso você consegue tocar um tipo de instrumento muito especial, a Flauta Demoníaca (Mateki). Dureza e Absorção: A Flauta Demoníaca possui Dureza 20 e somente quebra quando sua dureza é reduzida a 0. Porém, considere que o flautista está sempre protegendo a arma, fazendo com que ela somente possa ser atacada caso o atacante especifique que ela é o alvo e aceite uma penalidade de -3 na jogada de ataque.' },
  { id: slug('Ilusões Avançadas'), nome: 'Ilusões Avançadas', categoria: 'cla', gratuita: false, cla: 'Mateki', pagina: 106, livro: LIVRO, resumo: '[Vol. 2] Requer Arte 9, Flautista, Ilusão Profunda. Quando usar a Flauta Demoníaca, o cálculo de dificuldade é modificado para 9 + Nível de Arte do usuário, já inclusa a Ilusão Profunda. Além disso, você pode afetar mais de um alvo por uso de Fascinar. Para isso, a dificuldade do teste de resistência vai diminuir em 1 ponto +1 ponto para cada alvo (ou seja: -3 para dois alvos, -4 para três alvos, e assim por diante).' },
  { id: slug('Yoton Corrosivo'), nome: 'Yoton Corrosivo', categoria: 'cla', gratuita: false, cla: 'Mei Kekkei Genkai', pagina: 110, livro: LIVRO, resumo: '[Vol. 2] Requer Youton 5. Todo o efeito de Youton que estiver em contato com o inimigo (Dano Contínuo, Restringente, Carga de Lava, Onda Queimante) dão 2 de dano fixo por turno enquanto estiverem em contato.' },
  { id: slug('Futton Sufocante'), nome: 'Futton Sufocante', categoria: 'cla', gratuita: false, cla: 'Mei Kekkei Genkai', pagina: 110, livro: LIVRO, resumo: '[Vol. 2] Requer Futton 5 YOTON. Esta aptidão possui as mesmas regras do Domínio de Fogo Poder Restrito (Livro Básico, p.73), porém é aplicada exclusivamente para os efeitos do seu poder Futton.' },
  { id: slug('Dupla Linhagem'), nome: 'Dupla Linhagem', categoria: 'cla', gratuita: false, cla: 'Mei Kekkei Genkai', pagina: 110, livro: LIVRO, resumo: '[Vol. 2] Requer Espírito 10; Futton ou Youton 5. Ao comprar esta aptidão, você receberá gratuitamente o 1º Nível no outro poder restrito do Hijutsu que não foi primeiramente escolhido, e o poder elemental básico faltante. Você poderá obter e evoluir o outro poder restrito normalmente. Adicionalmente, esta aptidão permite usar qualquer efeito do seu primeiro poder Futton como se fosse Youton, e vice-versa, desde que o efeito seja disponível para ambos, recebendo todas as suas propriedades (bônus de dano, dureza, alcance...), e usando como parâmetro o nível de…', tecnicas: [tec(1, 'Carga de Lava', 'padrao', 0, 'Ação: Padrão Alcance: Comum do Poder Alvo: Único Dano: Comum do Poder Duração: Contínua O usuário atira 1 (uma) bola de lava em direção ao alvo que, se atingi-lo, Orbe(2), imediatamente se solidifica em seu corpo, gerando um peso extra. Cada Lança(3), carga de lava adiciona 1 compartimento totalmente preenchido sobre o Destrutivo(4), alvo. No turno do alvo, ele pode gastar uma ação parcial para quebrar todas as…'), tec(1, 'Onda Queimante', 'padrao', 0, 'Ação: Padrão Alcance: Comum do Poder Alvo: Único Dano: Nível Usado do Poder Duração: Contínua por 3 turnos (Ver Texto) O usuário projeta uma grande quantidade de lava para cobrir o corpo do alvo, que tem direito a teste de defesa. Se falhar, o alvo sofrerá o dano do efeito, como dano base, e depois sofrerá o dano novamente, como dano fixo, uma vez por turno. A cada turno, o alvo tem direito a um teste de Vigor (Dif…'), tec(1, 'Petrificação', 'padrao', 0, 'Ação: Padrão Alcance: Comum do Poder Alvo: Único Dano: Comum do Poder Duração: Contínua O usuário dispara um jato de lava sobre o alvo, que causa dano e depois se solidifica para prendê-lo. Após ser atingido pelo efeito, o alvo tem direito um teste de Vigor (Dif padrão -2). Se falhar, ficará impedido.'), tec(1, 'Sopro Concentrado', 'padrao', 0, 'Ação: Padrão Alcance: Comum do Poder Alvo: Único Dano: Comum do Poder Duração: Instantânea Selos de Mão: Não O usuário concentra uma pequena quantidade de vapor de sua boca e cospe em direção ao alvo como um jato fino, rápido e cortante. Este efeito não recebe penalidades por combate próximo e não pode ser bloqueado (a menos que seja um Bloqueio feito com uma arma especial que possa bloquear técnicas). Este efeito…'), tec(1, 'Neblina Ácida', 'padrao', 0, 'Ação: Padrão Alcance: Pessoal Área de Efeito: Esfera de Raio Comum do Poder (Ver Texto) Dano: Comum do Poder Duração: Instantânea ou Concentração Você emite uma neblina de vapor ácido de sua boca, capaz de se moldar ao ambiente e, descontroladamente, destruir todos no local. Esse efeito assume a área de uma esfera ao redor do usuário que ignora qualquer cobertura existente pois vai se expandindo e se moldando ao…')] },
  { id: slug('Extração Energética'), nome: 'Extração Energética', categoria: 'cla', gratuita: false, cla: 'Tensai', pagina: 115, livro: LIVRO, resumo: '[Vol. 2] Requer Espírito 6. Você é capaz de absorver chakra diretamente de uma fonte ou de um ser vivo. Contudo, para que isso seja possível, é necessário que a vítima esteja sob a condição indefeso. Absorver chakra é uma ação padrão e tem duração por concentração.' },
  { id: slug('Manipulação Física'), nome: 'Manipulação Física', categoria: 'cla', gratuita: false, cla: 'Tensai', pagina: 115, livro: LIVRO, resumo: '[Vol. 2] Requer Lutador; Vigor 4. Você desloca suas articulações e as torce, assim melhorando seu combate corporal. Corpo Esguio: Você recebe gratuitamente os benefícios da aptidão “Corpo Esguio” (Ver Guia Avançado do Shinobi, p.8). Agarrar Aprimorado: Ao comprar essa aptidão, você tem as seguintes opções ao usar a manobra agarrar: Agarramento Contorcionista: Você sacrifica sua defesa para agarrar o alvo com mais precisão.' },
  { id: slug('Efeito Estroboscópio'), nome: 'Efeito Estroboscópio', categoria: 'cla', gratuita: false, cla: 'Ranton', pagina: 119, livro: LIVRO, resumo: '[Vol. 2] Requer Ranton 6.. Sempre que causar dano com um efeito do poder Ranton, a vítima deverá fazer um teste de Vigor (Dif padrão -2). Falhando, ficará com a visão prejudicada, sofrendo Camuflagem Parcial contra seus inimigos até o final do próximo turno dela. Esta aptidão somente é aplicada a efeitos à distância que necessitem de teste de acerto contra a ação defensiva do alvo.' },
  { id: slug('Rinbo: Hengoku'), nome: 'Rinbo: Hengoku', categoria: 'cla', gratuita: false, cla: 'Ranton', pagina: 120, livro: LIVRO, resumo: '[Vol. 2] Requer Rinnegan (Esta Aptidão faz parte do Hijutsu Rinnegan);. Pré-requisitos: Rinnegan (Esta Aptidão faz parte do Hijutsu Rinnegan); Gedou (Caminho Externo); Clone Verdadeiro; Espírito 20; Ocultismo 20. Limitação: Uma vez comprada essa aptidão, você se torna incapaz de usar a “Reanimação” do Caminho Externo para sempre. Caso possua algum corpo reanimado, eles deverão sair de seu controle imediatamente.' },
  { id: slug('Mumificar'), nome: 'Mumificar', categoria: 'cla', gratuita: false, cla: 'Shakuton', pagina: 121, livro: LIVRO, resumo: '[Vol. 2] Requer Shakuton 5. Sempre que causar dano com um efeito do poder Shakuton, a vítima deverá fazer um teste de Vigor (Dif padrão -2). Falhando, causa dano estrutural aos tecidos do oponente, recebendo um nível de Sangramento (efetivamente, 2 de dano imediatamente quando começar o turno da vítima). Esta aptidão somente é aplicada a efeitos que necessitem de teste de acerto contra a ação defensiva do alvo, incluindo efeito Energizar.' },
  { id: slug('Barreira Regenerativa'), nome: 'Barreira Regenerativa', categoria: 'cla', gratuita: false, cla: 'Shouton', pagina: 124, livro: LIVRO, resumo: '[Vol. 2] Requer Shouton 5.. Na rodada seguinte após conjurar uma Barreira Shouton, caso ela resista até o começo do seu turno, você pode gastar uma ação livre para renovar sua dureza. Somente é possível aplicar este efeito uma única vez por barreira.' },
  { id: slug('Cristalização'), nome: 'Cristalização', categoria: 'cla', gratuita: false, cla: 'Shouton', pagina: 124, livro: LIVRO, resumo: '[Vol. 2] Requer Shouton 7; Congelamento (aptidão).. quando atingir um oponente que tenha sofrido os efeitos da aptidão Congelamento (de Shouton) na rodada anterior, você pode, como Ação Livre, pagar 4 pontos de chakra para aumentar em 1 o grau de dano da técnica que o atingiu, o grau de dano nunca pode superar “Grau 4”. Essa aptidão apenas pode afetar técnicas do Poder Shouton que requeiram teste de Acerto contra Defesa do Alvo.' },
  { id: slug('Cristal Guiado'), nome: 'Cristal Guiado', categoria: 'cla', gratuita: false, cla: 'Shouton', pagina: 125, livro: LIVRO, resumo: '[Vol. 2] Requer Shouton 5. Quando um inimigo evitar um de seus ataques à distância de um efeito Shouton, você pode refazer seu teste de ataque a cada rodada, e seu oponente também refaz sua defesa. Fazer isso requer que a técnica seja executada e mantida por concentração, e custa 2 pontos de chakra por rodada. Contudo, a efetividade da técnica diminui à medida que o alvo se acostuma com a velocidade do ataque.' },
  { id: slug('Souma no Kou (Ataque dos Demônios Gêmeos)'), nome: 'Souma no Kou (Ataque dos Demônios Gêmeos)', categoria: 'cla', gratuita: false, cla: 'Souma', pagina: 128, livro: LIVRO, resumo: '[Vol. 2] Requer Vigor 2. Você (Hospedeiro) possui um irmão gêmeo idêntico a você (Parasita) desde o dia em que nasceu e, por causa disso, você dois desenvolveram um jeito de lutarem juntos. Uma personagem será o Hospedeiro e a outra deverá ser do Parasita, ou seja, a pessoa que vive dentro do corpo do irmão. Ficha e Precisões: O Parasita possui ficha iguais ao do hospedeiro, porém com 2 níveis a menos em todos os atributos, habilidades e perícias (mínimo de nível zero; esta penalidade não conta no limite de penalidade de precisão).' },
  { id: slug('Regeneração Gêmea'), nome: 'Regeneração Gêmea', categoria: 'cla', gratuita: false, cla: 'Souma', pagina: 131, livro: LIVRO, resumo: '[Vol. 2] Requer Vigor 4; Souma no Kou Nv 1.. Você recebe os benefícios da aptidão Regeneração (Ver Clã Uzumaki, Livro Básico, Pág 193), mas somente enquanto os corpos estiverem fundidos. Quando um dos irmãos se ferir gravemente, eles podem se fundir e recuperar a vida do Parasita, enquanto o hospedeiro o protege. Um dos gêmeos assume o papel de “Parasita” e entra em hibernação.' },
  { id: slug('Mestre dos Leques'), nome: 'Mestre dos Leques', categoria: 'cla', gratuita: false, cla: 'Tessenjutsu', pagina: 132, livro: LIVRO, resumo: '[Vol. 2] Requer Destreza 6; Fuuton 3. Você recebe as aptidões Usar Arma Marcial (Leque Gigante), Especialista (Armas Longas) e Maestria: Fuuton. Mesmo que não possua os pré-requisitos necessários para as aptidões. Amortecer Queda: Caso esteja portando seu leque, toda vez que você for sofrer dano de queda, pode usar o leque para negar completamente o dano, fazer isso é uma ação livre e custa 1 ponto de chakra.' },
  { id: slug('Brisa de Navalha'), nome: 'Brisa de Navalha', categoria: 'cla', gratuita: false, cla: 'Tessenjutsu', pagina: 132, livro: LIVRO, resumo: '[Vol. 2] Requer Espírito 10; Fuuton 5. Você é capaz de utilizar o efeito Lâmina de Vento 7 para Fuuton, mesmo sem possuir o nível necessário. O dano base de cada lâmina é igual a 3 (dano base + bônus do elemento) e pode criar 1 lâmina por nível de Espírito dividido por dois (arredondado para baixo). O custo de chakra é metade do nível de Espírito (arredondado para cima).' },
  { id: slug('Capacidade dos Ventos'), nome: 'Capacidade dos Ventos', categoria: 'cla', gratuita: false, cla: 'Tessenjutsu', pagina: 133, livro: LIVRO, resumo: '[Vol. 2] Requer Espírito ou Inteligência 12. Desde que esteja utilizando com um Leque Gigante, você pode utilizar as meta aptidões Potencializar e Técnica Poderosa como Ação Parcial para Fuuton. Leque Afiado: Caso seu Leque Gigante esteja afiado pelo efeito Afiar, o dano de arma do Leque Gigante aumenta de +4 para +5. Maximizar: [Requer Espírito ou Inteligência 15] Você recebe a aptidão Maximizar (Ver Livro Básico, p.175), porém para o seu poder Fuuton.' },
  { id: slug('Anatomia Zetsu'), nome: 'Anatomia Zetsu', categoria: 'cla', gratuita: false, cla: 'Zetsu', pagina: 134, livro: LIVRO, resumo: '[Vol. 2] Você é imune a sangramento, de qualquer que seja a fonte (pois não possui sangue), não precisa comer ou dormir. [Requer Disfarce 10] Você pode moldar seu corpo à própria vontade, assumindo a forma mais útil para cada situação. O limite das modificações corporais está sujeito ao Narrador. Além disso, você recebe +2 de Precisão para sair de agarramento e algemas (inclusive o efeito Algemar). [Requer “Usar Arma”] Você pode moldar seus membros para criar armas naturais iguais à arma corpo a corpo não especiais que…' },
  { id: slug('Clone Zetsu'), nome: 'Clone Zetsu', categoria: 'cla', gratuita: false, cla: 'Zetsu', pagina: 135, livro: LIVRO, resumo: '[Vol. 2] Requer Clone (aptidão).. Clones Zetsus funcionam exatamente como Moku Bunshins e podem evoluir com as outras aptidões de clone (Clone Nv 2; Clone Verdadeiro). Além disso, eles são clones perfeitos e totalmente capazes de substituir o original. Uma vez que o “corpo principal” morra, qualquer dos clones pode assumir o posto de PJ (ou PdM Principal), porém seu chakra e vitalidade não aumentam instantaneamente.' },
  { id: slug('Elementos Irrestritos'), nome: 'Elementos Irrestritos', categoria: 'cla', gratuita: false, cla: 'Zetsu', pagina: 135, livro: LIVRO, resumo: '[Vol. 2] Requer Espírito 10; Mokuton 5.. A personagem recebe gratuitamente 1 Nível em todos os cinco elementos básicos e pode utilizar o efeito Canhão para qualquer dos elementos básicos usando o nível de Mokuton como nível efetivo da técnica. Além disso, você pode comprar níveis em qualquer dos cinco elementos básicos para conseguir mais efeitos. Ao comprar esta aptidão, você passa a não sofrer mais o limite da regra de afinidade elemental (Livro Básico, p.89).', tecnicas: [tec(1, 'Efemeróptero', 'padrao', 0, 'Para usar este efeito, você deve estar sob o benefício do efeito Imergir (Doton), sob o solo, paga 5 pontos de chakra e precisa se concentrar inicialmente durante 1 minuto. Após isso, enquanto mantiver concentração, você é capaz de se mover em alta velocidade debaixo da terra, usando as plantas, suas raízes e a terra como condutor. Você é capaz de se deslocar 50m por Nível de Espírito instantaneamente a cada 6…', { fica: 'Efemeróptero (concentração)' }), tec(1, 'Chuva de Esporos', 'completa', 'nivel', 'Você é capaz de dispersar esporos ao seu redor ou a partir de um Clone Zetsu, fazer isso é uma jogada de CD contra todos na área, que podem realizar suas defesas normalmente. Quem falhar na defesa é infectado pelos esporos, que começam a drenar chakra a cada turno e a crescer neste processo. O chakra drenado é igual à metade do nível do poder usado.')] },
  { id: slug('Kuchiyose: Rashoumon'), nome: 'Kuchiyose: Rashoumon', categoria: 'cla', gratuita: false, cla: 'Kuchiyose', pagina: 141, livro: LIVRO, resumo: '[Vol. 2] Requer Espírito ou Inteligência 8. [Invocação para o poder Kuchiyose] Os portões sul da antiga capital japonesa do período Nara e de uma das antigas cidades que dariam origem ao que conhecemos hoje como Kyoto, são uma poderosa invocação defensiva que surge como um grande paredão com a face de um oni, sendo supostamente impenetrável. Pré-requisito: Espírito ou Inteligência 8 Ninjutsu / Invocação Ação: Movimento Alcance: 5 + 1m por Nível de Espírito ou Inteligência Área de Efeito: Parede de largura e altura igual a ½ m por Nível de Espírito ou Inteligência Dureza: Nível de Espírito ou…' },
];

